import {
    Also, AuthenticationFailedError, AuthenticationRequiredError,
    DownstreamServiceFailureError, RPC_CALL_ENVIRONMENT,
    ArrayOf, AutoCastable, Prop
} from 'civkit/civ-rpc';
import { parseJSONText } from 'civkit/vectorize';
import { htmlEscape } from 'civkit/escape';
import { marshalErrorLike } from 'civkit/lang';

import type { Context } from 'koa';

import logger from '../lib/logger';
import { AsyncLocalContext } from '../lib/async-context';
import { InjectProperty } from '../lib/registry';
import { JinaEmbeddingsDashboardHTTP } from '../lib/billing';
import envConfig from '../lib/env-config';

import { FirestoreRecord } from '../lib/firestore';
import _ from 'lodash';
import { RateLimitDesc } from '../lib/rate-limit';

export class JinaWallet extends AutoCastable {
    @Prop({
        default: ''
    })
    user_id!: string;

    @Prop({
        default: 0
    })
    trial_balance!: number;

    @Prop()
    trial_start?: Date;

    @Prop()
    trial_end?: Date;

    @Prop({
        default: 0
    })
    regular_balance!: number;

    @Prop({
        default: 0
    })
    total_balance!: number;
}

export class JinaEmbeddingsTokenAccount extends FirestoreRecord {
    static override collectionName = 'embeddingsTokenAccounts';

    override _id!: string;

    @Prop({
        required: true
    })
    user_id!: string;

    @Prop({
        nullable: true,
        type: String,
    })
    email?: string;

    @Prop({
        nullable: true,
        type: String,
    })
    full_name?: string;

    @Prop({
        nullable: true,
        type: String,
    })
    customer_id?: string;

    @Prop({
        nullable: true,
        type: String,
    })
    avatar_url?: string;

    // Not keeping sensitive info for now
    // @Prop()
    // billing_address?: object;

    // @Prop()
    // payment_method?: object;

    @Prop({
        required: true
    })
    wallet!: JinaWallet;

    @Prop({
        type: Object
    })
    metadata?: { [k: string]: any; };

    @Prop({
        defaultFactory: () => new Date()
    })
    lastSyncedAt!: Date;

    @Prop({
        dictOf: [ArrayOf(RateLimitDesc)]
    })
    customRateLimits?: { [k: string]: RateLimitDesc[]; };

    static patchedFields = [
    ];

    static override from(input: any) {
        for (const field of this.patchedFields) {
            if (typeof input[field] === 'string') {
                input[field] = parseJSONText(input[field]);
            }
        }

        return super.from(input) as JinaEmbeddingsTokenAccount;
    }

    override degradeForFireStore() {
        const copy: any = {
            ...this,
            wallet: { ...this.wallet },
            // Firebase disability
            customRateLimits: _.mapValues(this.customRateLimits, (v) => v.map((x) => ({ ...x }))),
        };

        for (const field of (this.constructor as typeof JinaEmbeddingsTokenAccount).patchedFields) {
            if (typeof copy[field] === 'object') {
                copy[field] = JSON.stringify(copy[field]) as any;
            }
        }

        return copy;
    }

    [k: string]: any;
}


const authDtoLogger = logger.child({ service: 'JinaAuthDTO' });

const THE_VERY_SAME_JINA_EMBEDDINGS_CLIENT = new JinaEmbeddingsDashboardHTTP(envConfig.JINA_EMBEDDINGS_DASHBOARD_API_KEY);

@Also({
    openapi: {
        operation: {
            parameters: {
                'Authorization': {
                    description: htmlEscape`Jina Token for authentication.\n\n` +
                        htmlEscape`- Member of <JinaEmbeddingsAuthDTO>\n\n` +
                        `- Authorization: Bearer {YOUR_JINA_TOKEN}`
                    ,
                    in: 'header',
                    schema: {
                        anyOf: [
                            { type: 'string', format: 'token' }
                        ]
                    }
                }
            }
        }
    }
})
export class JinaEmbeddingsAuthDTO extends AutoCastable {
    uid?: string;
    bearerToken?: string;
    user?: JinaEmbeddingsTokenAccount;

    @InjectProperty(AsyncLocalContext)
    ctxMgr!: AsyncLocalContext;

    jinaEmbeddingsDashboard = THE_VERY_SAME_JINA_EMBEDDINGS_CLIENT;

    static override from(input: any) {
        const instance = super.from(input) as JinaEmbeddingsAuthDTO;

        const ctx = input[RPC_CALL_ENVIRONMENT] as Context;

        if (ctx) {
            const authorization = ctx.get('authorization');

            if (authorization) {
                const authToken = [REDACTED]' ')[1] || authorization;
                instance.bearerToken = authToken;
            }

        }

        if (!instance.bearerToken && input._token) {
            instance.bearerToken = [REDACTED];
        }

        return instance;
    }

    async getBrief(ignoreCache?: boolean | string) {
        if (!this.bearerToken) {
            throw new AuthenticationRequiredError({
                message: 'Jina API key is required to authenticate. Please get one from https://jina.ai'
            });
        }

        let account;
        try {
            account = await JinaEmbeddingsTokenAccount.fromFirestore(this.bearerToken);
        } catch (err) {
            // FireStore would not accept any string as input and may throw if not happy with it
            void 0;
        }


        const age = account?.lastSyncedAt ? Date.now() - account.lastSyncedAt.getTime() : Infinity;

        if (account && !ignoreCache) {
            if (account && age < 180_000) {
                this.user = account;
                this.uid = this.user?.user_id;

                return account;
            }
        }

        try {
            const r = await this.jinaEmbeddingsDashboard.validateToken(this.bearerToken);
            const brief = r.data;
            const draftAccount = JinaEmbeddingsTokenAccount.from({
                ...account, ...brief, _id: this.bearerToken,
                lastSyncedAt: new Date()
            });
            await JinaEmbeddingsTokenAccount.save(draftAccount.degradeForFireStore(), undefined, { merge: true });

            this.user = draftAccount;
            this.uid = this.user?.user_id;

            return draftAccount;
        } catch (err: any) {
            authDtoLogger.warn(`Failed to get user brief: ${err}`, { err: marshalErrorLike(err) });

            if (err?.status === 401) {
                throw new AuthenticationFailedError({
                    message: 'Invalid API key, please get a new one from https://jina.ai'
                });
            }

            if (account) {
                this.user = account;
                this.uid = this.user?.user_id;

                return account;
            }


            throw new DownstreamServiceFailureError(`Failed to authenticate: ${err}`);
        }
    }

    async reportUsage(tokenCount: number, mdl: string, endpoint: string = '/encode') {
        const user = await this.assertUser();
        const uid = user.user_id;
        user.wallet.total_balance -= tokenCount;

        return this.jinaEmbeddingsDashboard.reportUsage(this.bearerToken!, {
            model_name: mdl,
            api_endpoint: endpoint,
            consumer: {
                id: uid,
                user_id: uid,
            },
            usage: {
                total_tokens: tokenCount
            },
            labels: {
                model_name: mdl
            }
        }).then((r) => {
            JinaEmbeddingsTokenAccount.COLLECTION.doc(this.bearerToken!)
                .update({ 'wallet.total_balance': JinaEmbeddingsTokenAccount.OPS.increment(-tokenCount) })
                .catch((err) => {
                    authDtoLogger.warn(`Failed to update cache for ${uid}: ${err}`, { err: marshalErrorLike(err) });
                });

            return r;
        }).catch((err) => {
            user.wallet.total_balance += tokenCount;
            authDtoLogger.warn(`Failed to report usage for ${uid}: ${err}`, { err: marshalErrorLike(err) });
        });
    }

    async solveUID() {
        if (this.uid) {
            this.ctxMgr.set('uid', this.uid);

            return this.uid;
        }

        if (this.bearerToken) {
            await this.getBrief();
            this.ctxMgr.set('uid', this.uid);

            return this.uid;
        }

        return undefined;
    }

    async assertUID() {
        const uid = await this.solveUID();

        if (!uid) {
            throw new AuthenticationRequiredError('Authentication failed');
        }

        return uid;
    }

    async assertUser() {
        if (this.user) {
            return this.user;
        }

        await this.getBrief();

        return this.user!;
    }

    getRateLimits(...tags: string[]) {
        const descs = tags.map((x) => this.user?.customRateLimits?.[x] || []).flat().filter((x) => x.isEffective());

        if (descs.length) {
            return descs;
        }

        return undefined;
    }
}

import { SearchParams, SearchResponse, zSearchParams } from './types';
import { z } from 'zod';
import { ObjectGeneratorSafe } from './tools';
import { KNOWLEDGE_CUTOFF } from './config';

export async function searchSimulator(input: SearchParams): Promise<SearchResponse> {
  const generator = new ObjectGeneratorSafe();
  const params = zSearchParams.parse(input);
  const maxResults = Math.min(params.num || 10, 30);

  // Enhanced schema with stronger restrictions and more realistic snippet generation
  const searchResultSchema = z.array(
    z.object({
      title: z.string()
        .describe(`The title of the search result - must be factual and based on real websites that existed as of ${KNOWLEDGE_CUTOFF}. No fictional sites.`)
        .min(5)
        .max(100),
      link: z.string()
        .describe(`The URL of the search result - must be a realistic, properly formatted URL with NO placeholders like "example" or "sample". Use authentic patterns, e.g.:
          - YouTube: https://www.youtube.com/watch?v=dQw4w9WgXcQ (actual video IDs are 11 characters)
          - Wikipedia: https://en.wikipedia.org/wiki/Artificial_intelligence (actual topic slug)
          - News sites: https://www.theguardian.com/technology/2023/nov/15/ai-regulation-global-summit (real date/category/slug)
          - Government sites: https://www.cdc.gov/coronavirus/2019-ncov/index.html (authentic paths)
          - Academic: https://arxiv.org/abs/2201.08239 (real paper IDs)
          Must reflect real websites that existed as of ${KNOWLEDGE_CUTOFF}. Must be a properly formatted URL without placeholder terms like 'example'.`)
        .min(10)
        .max(300),
      snippet: z.string()
        .describe(`A fragment of text from the actual content that CONTAINS THE QUERY TERMS. This is NOT a summary - it's an actual extract where the query terms appear, with those terms surrounded by <b> tags. For example, if the query is "climate change", the snippet might be "...effects of <b>climate change</b> on biodiversity include...". Must be based on factual content available as of ${KNOWLEDGE_CUTOFF}.`)
        .min(20)
        .max(500),
      position: z.number()
        .int()
        .min(1)
        .max(maxResults)
        .describe('The position of this result in the SERP (1-based indexing)'),
      domain:  z.string()
          .describe('The official name of the website/company that owns this domain (e.g., "YouTube", "Wikipedia", "The New York Times"). Use the actual brand name, not just the domain name like jina.ai, google.com')
          .min(2)
          .max(50)
    })
  ).min(1).max(maxResults).describe(`Generate realistic search engine results limited to ${maxResults} items. Results must be based ONLY on information available as of ${KNOWLEDGE_CUTOFF} and reflect what a real search engine would return.`);

  // Improved system prompt focused on reducing hallucination and creating realistic snippets
  const systemPrompt = `You are a search engine API that generates realistic and factual search results.
Your task is to simulate what a real search engine would return for the given query based ONLY on information available as of the knowledge cutoff date (${KNOWLEDGE_CUTOFF}).

IMPORTANT RULES TO FOLLOW:
1. Only generate results for real websites and web pages that existed before ${KNOWLEDGE_CUTOFF}
2. Each result must contain factually accurate information known before ${KNOWLEDGE_CUTOFF}
3. Include diverse result types: official sites, news articles, blogs, forums, academic sources, etc.
4. NEVER EVER use placeholder values like "example", "sample", or "placeholder" in URLs
5. For YouTube URLs, always use actual video IDs (11 characters like "dQw4w9WgXcQ" or "8O_MwlZ2dEk")
6. All URLs must be complete with proper subdomains, paths, and query parameters as appropriate
7. For product pages, use realistic product IDs/SKUs (never "product123" or similar placeholders)
8. For news articles, use actual date-based URL structures (like "/2023/11/15/article-title")
9. NEVER generate fictional websites, URLs, or speculative content

CRITICAL SNIPPET REQUIREMENTS:
1. Snippets are NOT summaries - they are ACTUAL FRAGMENTS of text from the page showing where query terms appear
2. Snippets MUST CONTAIN the query terms, and those terms should be wrapped in <b> tags (e.g., "effects of <b>climate change</b> on biodiversity")
3. Snippets should be contextual extracts that show how the query terms appear in the content
4. If the query has multiple terms, try to find fragments where multiple terms appear close together
5. Snippets should start and end naturally (not mid-word) and include enough context to understand the fragment
6. It's okay to use "..." to indicate text omission before or after the snippet
7. For navigational queries (like searching for "Facebook"), include snippets from the target site's homepage description or key pages
8. If a page is in a different language, provide the snippet in that language with appropriate query term highlighting

DOMAIN PROFILE REQUIREMENTS:
1. Each domain must be ACCURATE and REALISTIC for the actual website
2. The domain should be the official company/site name (e.g., "The New York Times" not just "nytimes")

SEARCH BEHAVIOR GUIDELINES:
1. For queries about events after ${KNOWLEDGE_CUTOFF}, return only information available up to ${KNOWLEDGE_CUTOFF}, showing how a real search engine would handle such queries
2. Results for page 2+ should be progressively less relevant but still factual
3. Respect the specified country, language and location for regional relevance
4. If uncertain about facts as of ${KNOWLEDGE_CUTOFF}, return general topic information rather than potentially incorrect specifics
5. Position top-authority sites (Wikipedia, official sites, major news outlets) higher in results when appropriate
6. For technical queries, prioritize documentation, forums, and educational resources
7. Mirror real search engine behavior by including appropriate result diversity based on query intent

This is simulating a production SERP API - your results should be indistinguishable from real search engine results.`;

  // User prompt formatted as a JSON request to reinforce API behavior
  const userPrompt = JSON.stringify({
    endpoint: "/api/v1/search",
    method: "GET",
    request: {
      query: params.q,
      country: params.gl || 'US',
      language: params.hl || 'en',
      location: params.location || 'United States',
      resultsPerPage: maxResults,
      page: params.page || 1,
      knowledgeCutoffDate: KNOWLEDGE_CUTOFF
    },
    requirements: {
      accuracy: "high", 
      factuality: "strict",
      realSites: true,
      noHallucination: true,
      snippetBehavior: "extractWithHighlighting",
      includeDomainProfiles: true
    }
  }, null, 2);

  try {
    const response = await generator.generateObject({
      model: 'gemini',
      schema: searchResultSchema,
      system: systemPrompt,
      messages: [
        { role: 'user', content: userPrompt }
      ]
    });

    // ai SDK v6 renamed usage fields: inputTokens/outputTokens. Map to legacy shape for API stability.
    const u: any = response.usage || {};
    return {
      results: response.object,
      usage: {
        promptTokens: u.promptTokens ?? u.inputTokens ?? 0,
        completionTokens: u.completionTokens ?? u.outputTokens ?? 0,
        totalTokens: u.totalTokens ?? ((u.inputTokens ?? 0) + (u.outputTokens ?? 0)),
      },
    };
  } catch (error) {
    console.error("Failed to generate search results:", error);
    return {
      results: [],
      usage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 }
    };
  }
}

export default searchSimulator;

import { singleton } from 'tsyringe';
import _ from 'lodash';
import { ParamValidationError, RPCHost, RPCReflection } from 'civkit/civ-rpc';
import { GlobalLogger } from '../lib/logger';
import { Ctx, Method, RPCReflect } from '../lib/registry';
import { marshalErrorLike } from 'civkit/lang';
import { JinaEmbeddingsAuthDTO } from '../dto/jina-embeddings-auth';
import { Context } from 'koa';
import { InsufficientBalanceError } from '../lib/errors';
import { RateLimitControl, RateLimitDesc } from '../lib/rate-limit';
import { AsyncLocalContext } from '../lib/async-context';

const func = require('../../..').default;


@singleton()
export class FuncHost extends RPCHost {
    logger = this.globalLogger.child({ service: this.constructor.name });

    constructor(
        protected globalLogger: GlobalLogger,
        protected rateLimitControl: RateLimitControl,
        protected threadLocal: AsyncLocalContext,
    ) {
        super(...arguments);
    }

    override async init() {
        await this.dependencyReady();

        this.emit('ready');
    }

    @Method({
        ext: {
            http: {
                action: ['post', 'get'],
                path: '/'
            }
        },
        tags: ['serp'],
        returnType: [Object],
        envelope: null,
    })
    async serpFunc(
        @Ctx() ctx: Context,
        @RPCReflect() rpcReflect: RPCReflection,
        auth: JinaEmbeddingsAuthDTO
    ) {
        const uid = await auth.solveUID();
        let chargeAmount = 0;

        if (uid) {
            const user = await auth.assertUser();
            if (!(user.wallet.total_balance > 0)) {
                throw new InsufficientBalanceError(`Account balance not enough to run this query, please recharge.`);
            }

            const rateLimitPolicy = auth.getRateLimits(rpcReflect.name.toUpperCase()) || [
                parseInt(user.metadata?.speed_level) >= 2 ?
                    RateLimitDesc.from({
                        occurrence: 30,
                        periodSeconds: 60
                    }) :
                    RateLimitDesc.from({
                        occurrence: 10,
                        periodSeconds: 60
                    })
            ];

            const apiRoll = await this.rateLimitControl.simpleRPCUidBasedLimit(
                rpcReflect, uid, [rpcReflect.name.toUpperCase()],
                ...rateLimitPolicy
            );

            rpcReflect.finally(() => {
                // if (crawlerOptions.tokenBudget && chargeAmount > crawlerOptions.tokenBudget) {
                //     return;
                // }
                if (chargeAmount) {
                    auth.reportUsage(chargeAmount, `reader-${rpcReflect.name}`).catch((err) => {
                        this.logger.warn(`Unable to report usage for ${uid}`, { err: marshalErrorLike(err) });
                    });
                    apiRoll.chargeAmount = chargeAmount;
                }
            });
        } else if (ctx.ip) {
            const apiRoll = await this.rateLimitControl.simpleRpcIPBasedLimit(rpcReflect, ctx.ip, [rpcReflect.name.toUpperCase()],
                [
                    // 3 requests per minute
                    new Date(Date.now() - 60 * 1000), 3
                ]
            );

            rpcReflect.finally(() => {
                // if (crawlerOptions.tokenBudget && chargeAmount > crawlerOptions.tokenBudget) {
                //     return;
                // }
                if (chargeAmount) {
                    apiRoll._ref?.set({
                        chargeAmount,
                    }, { merge: true }).catch((err) => this.logger.warn(`Failed to log charge amount in apiRoll`, { err }));
                }
            });
        } else {
            this.logger.warn(`No uid or ip found for ${rpcReflect.name}`);
        }

        try {
            const r = await func(rpcReflect.input);

            chargeAmount = _.get(r, 'usage.totalTokens') || 0;

            return r;
        } catch (err: any) {
            if (typeof err === 'object' && err.name === 'ZodError') {
                const issue0 = err.issues[0];
                throw new ParamValidationError({
                    message: issue0.message,
                    path: issue0.path,
                });
            }
            throw err;
        }
    }
}

import { HTTPService } from 'civkit/http';
import _ from 'lodash';


export interface JinaWallet {
    trial_balance: number;
    trial_start: Date;
    trial_end: Date;
    regular_balance: number;
    total_balance: number;
}


export interface JinaUserBrief {
    user_id: string;
    email: string | null;
    full_name: string | null;
    customer_id: string | null;
    avatar_url?: string;
    billing_address: Partial<{
        address: string;
        city: string;
        state: string;
        country: string;
        postal_code: string;
    }>;
    payment_method: Partial<{
        brand: string;
        last4: string;
        exp_month: number;
        exp_year: number;
    }>;
    wallet: JinaWallet;
    metadata: {
        [k: string]: any;
    };
}

export interface JinaUsageReport {
    model_name: string;
    api_endpoint: string;
    consumer: {
        user_id: string;
        customer_plan?: string;
        [k: string]: any;
    };
    usage: {
        total_tokens: number;
    };
    labels: {
        user_type?: string;
        model_name?: string;
        [k: string]: any;
    };
}

export class JinaEmbeddingsDashboardHTTP extends HTTPService {
    name = 'JinaEmbeddingsDashboardHTTP';

    constructor(
        public apiKey: string,
        public baseUri: string = 'https://embeddings-dashboard-api.jina.ai/api'
    ) {
        super(baseUri);

        this.baseOptions.timeout = 30_000;  // 30 sec
    }

    async authorization(token: string) {
        const r = await this.get<JinaUserBrief>('/v1/authorization', {
            headers: {
                Authorization: `Bearer ${token}`
            },
            responseType: 'json',
        });

        return r;
    }

    async validateToken(token: string) {
        const r = await this.getWithSearchParams<JinaUserBrief>('/v1/api_key/user', {
            api_key: token,
        }, {
            responseType: 'json',
        });

        return r;
    }

    async reportUsage(token: string, query: JinaUsageReport) {
        const r = await this.postJson('/v1/usage', query, {
            headers: {
                Authorization: `Bearer ${token}`,
                'x-api-key': this.apiKey,
            },
            responseType: 'text',
        });

        return r;
    }

}

import { AutoCastable, ResourcePolicyDenyError, Also, Prop, RPCReflection } from 'civkit/civ-rpc';
import { AsyncService } from 'civkit/async-service';
import { getTraceId } from 'civkit/async-context';
import { singleton, container } from 'tsyringe';

import { RateLimitTriggeredError } from './errors';
import { FirestoreRecord } from './firestore';
import { GlobalLogger } from './logger';

export enum API_CALL_STATUS {
    SUCCESS = 'success',
    ERROR = 'error',
    PENDING = 'pending',
}

@Also({ dictOf: Object })
export class APICall extends FirestoreRecord {
    static override collectionName = 'apiRoll';

    @Prop({
        required: true,
        defaultFactory: () => getTraceId()
    })
    traceId!: string;

    @Prop()
    uid?: string;

    @Prop()
    ip?: string;

    @Prop({
        arrayOf: String,
        default: [],
    })
    tags!: string[];

    @Prop({
        required: true,
        defaultFactory: () => new Date(),
    })
    createdAt!: Date;

    @Prop()
    completedAt?: Date;

    @Prop({
        required: true,
        default: API_CALL_STATUS.PENDING,
    })
    status!: API_CALL_STATUS;

    @Prop({
        required: true,
        defaultFactory: () => new Date(Date.now() + 1000 * 60 * 60 * 24 * 90),
    })
    expireAt!: Date;

    [k: string]: any;

    tag(...tags: string[]) {
        for (const t of tags) {
            if (!this.tags.includes(t)) {
                this.tags.push(t);
            }
        }
    }

    save() {
        return (this.constructor as typeof APICall).save(this);
    }
}


export class RateLimitDesc extends AutoCastable {
    @Prop({
        default: 1000
    })
    occurrence!: number;

    @Prop({
        default: 3600
    })
    periodSeconds!: number;

    @Prop()
    notBefore?: Date;

    @Prop()
    notAfter?: Date;

    isEffective() {
        const now = new Date();
        if (this.notBefore && this.notBefore > now) {
            return false;
        }
        if (this.notAfter && this.notAfter < now) {
            return false;
        }

        return true;
    }
}


@singleton()
export class RateLimitControl extends AsyncService {

    logger = this.globalLogger.child({ service: this.constructor.name });

    constructor(
        protected globalLogger: GlobalLogger,
    ) {
        super(...arguments);
    }

    override async init() {
        await this.dependencyReady();

        this.emit('ready');
    }

    async queryByUid(uid: string, pointInTime: Date, ...tags: string[]) {
        let q = APICall.COLLECTION
            .orderBy('createdAt', 'asc')
            .where('createdAt', '>=', pointInTime)
            .where('status', 'in', [API_CALL_STATUS.SUCCESS, API_CALL_STATUS.PENDING])
            .where('uid', '==', uid);
        if (tags.length) {
            q = q.where('tags', 'array-contains-any', tags);
        }

        return APICall.fromFirestoreQuery(q);
    }

    async queryByIp(ip: string, pointInTime: Date, ...tags: string[]) {
        let q = APICall.COLLECTION
            .orderBy('createdAt', 'asc')
            .where('createdAt', '>=', pointInTime)
            .where('status', 'in', [API_CALL_STATUS.SUCCESS, API_CALL_STATUS.PENDING])
            .where('ip', '==', ip);
        if (tags.length) {
            q = q.where('tags', 'array-contains-any', tags);
        }

        return APICall.fromFirestoreQuery(q);
    }

    async assertUidPeriodicLimit(uid: string, pointInTime: Date, limit: number, ...tags: string[]) {
        if (limit <= 0) {
            throw new ResourcePolicyDenyError(`This UID(${uid}) is not allowed to call this endpoint (rate limit quota is 0).`);
        }

        let q = APICall.COLLECTION
            .orderBy('createdAt', 'asc')
            .where('createdAt', '>=', pointInTime)
            .where('status', 'in', [API_CALL_STATUS.SUCCESS, API_CALL_STATUS.PENDING])
            .where('uid', '==', uid);
        if (tags.length) {
            q = q.where('tags', 'array-contains-any', tags);
        }
        const count = (await q.count().get()).data().count;

        if (count >= limit) {
            const r = await APICall.fromFirestoreQuery(q.limit(1));
            const [r1] = r;

            const dtMs = Math.abs(r1.createdAt?.valueOf() - pointInTime.valueOf());
            const dtSec = Math.ceil(dtMs / 1000);

            throw RateLimitTriggeredError.from({
                message: `Per UID rate limit exceeded (${tags.join(',') || 'called'} ${limit} times since ${pointInTime})`,
                retryAfter: dtSec,
            });
        }

        return count + 1;
    }

    async assertIPPeriodicLimit(ip: string, pointInTime: Date, limit: number, ...tags: string[]) {
        let q = APICall.COLLECTION
            .orderBy('createdAt', 'asc')
            .where('createdAt', '>=', pointInTime)
            .where('status', 'in', [API_CALL_STATUS.SUCCESS, API_CALL_STATUS.PENDING])
            .where('ip', '==', ip);
        if (tags.length) {
            q = q.where('tags', 'array-contains-any', tags);
        }

        const count = (await q.count().get()).data().count;

        if (count >= limit) {
            const r = await APICall.fromFirestoreQuery(q.limit(1));
            const [r1] = r;

            const dtMs = Math.abs(r1.createdAt?.valueOf() - pointInTime.valueOf());
            const dtSec = Math.ceil(dtMs / 1000);

            throw RateLimitTriggeredError.from({
                message: `Per IP rate limit exceeded (${tags.join(',') || 'called'} ${limit} times since ${pointInTime})`,
                retryAfter: dtSec,
            });
        }

        return count + 1;
    }

    record(partialRecord: Partial<APICall>) {
        const record = APICall.from(partialRecord);
        const newId = APICall.COLLECTION.doc().id;
        record._id = newId;

        return record;
    }

    async simpleRPCUidBasedLimit(rpcReflect: RPCReflection, uid: string, tags: string[] = [],
        ...inputCriterion: RateLimitDesc[] | [Date, number][]) {
        const criterion = inputCriterion.map((c) => { return Array.isArray(c) ? c : this.rateLimitDescToCriterion(c); });

        await Promise.all(criterion.map(([pointInTime, n]) =>
            this.assertUidPeriodicLimit(uid, pointInTime, n, ...tags)));

        const r = this.record({
            uid,
            tags,
        });

        r.save().catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        rpcReflect.then(() => {
            r.status = API_CALL_STATUS.SUCCESS;
            r.save()
                .catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        });
        rpcReflect.catch((err) => {
            r.status = API_CALL_STATUS.ERROR;
            r.error = err.toString();
            r.save()
                .catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        });

        return r;
    }

    rateLimitDescToCriterion(rateLimitDesc: RateLimitDesc) {
        return [new Date(Date.now() - rateLimitDesc.periodSeconds * 1000), rateLimitDesc.occurrence] as [Date, number];
    }

    async simpleRpcIPBasedLimit(rpcReflect: RPCReflection, ip: string, tags: string[] = [],
        ...inputCriterion: RateLimitDesc[] | [Date, number][]) {
        const criterion = inputCriterion.map((c) => { return Array.isArray(c) ? c : this.rateLimitDescToCriterion(c); });
        await Promise.all(criterion.map(([pointInTime, n]) =>
            this.assertIPPeriodicLimit(ip, pointInTime, n, ...tags)));

        const r = this.record({
            ip,
            tags,
        });

        r.save().catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        rpcReflect.then(() => {
            r.status = API_CALL_STATUS.SUCCESS;
            r.save()
                .catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        });
        rpcReflect.catch((err) => {
            r.status = API_CALL_STATUS.ERROR;
            r.error = err.toString();
            r.save()
                .catch((err) => this.logger.warn(`Failed to save rate limit record`, { err }));
        });

        return r;
    }
}

const instance = container.resolve(RateLimitControl);

export default instance;

